"use client";

import type { ReactNode } from "react";
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/components/ui/resizable";
import { cn } from "@/lib/utils";

interface ResizableIDELayoutProps {
  fileTree: ReactNode;
  editor: ReactNode;
  preview: ReactNode;
  console: ReactNode;
  className?: string;
  defaultConsoleSize?: number;
}

export function ResizableIDELayout({
  fileTree,
  editor,
  preview,
  console,
  className,
  defaultConsoleSize = 22,
}: ResizableIDELayoutProps) {
  return (
    <div
      className={cn(
        "overflow-hidden rounded-xl border border-white/[0.06] bg-[#0c0c0e] shadow-2xl shadow-black/40 ring-1 ring-white/[0.04]",
        className
      )}
    >
      <div className="flex items-center gap-2 border-b border-white/[0.06] bg-[#101012] px-3 py-2">
        <div className="flex gap-1.5">
          <span className="size-2.5 rounded-full bg-[#3f3f46]" />
          <span className="size-2.5 rounded-full bg-[#3f3f46]" />
          <span className="size-2.5 rounded-full bg-[#3f3f46]" />
        </div>
        <span className="ml-2 font-mono text-[10px] text-zinc-500">
          counter-demo — shadcn-sandbox
        </span>
      </div>
      <ResizablePanelGroup orientation="vertical" className="min-h-[560px]">
        <ResizablePanel defaultSize={100 - defaultConsoleSize} minSize={45}>
          <ResizablePanelGroup orientation="horizontal">
            <ResizablePanel defaultSize={20} minSize={16} maxSize={30}>
              <div className="h-full border-r border-white/[0.06]">{fileTree}</div>
            </ResizablePanel>
            <ResizableHandle withHandle className="bg-white/[0.04]" />
            <ResizablePanel defaultSize={38} minSize={26}>
              <div className="h-full border-r border-white/[0.06]">{editor}</div>
            </ResizablePanel>
            <ResizableHandle withHandle className="bg-white/[0.04]" />
            <ResizablePanel defaultSize={42} minSize={24}>
              <div className="h-full">{preview}</div>
            </ResizablePanel>
          </ResizablePanelGroup>
        </ResizablePanel>
        <ResizableHandle withHandle className="bg-white/[0.04]" />
        <ResizablePanel defaultSize={defaultConsoleSize} minSize={12} maxSize={40}>
          <div className="h-full border-t border-white/[0.06]">{console}</div>
        </ResizablePanel>
      </ResizablePanelGroup>
    </div>
  );
}

import type { FileTreeNode, SandboxFile } from "./types";

export function getLanguageLabel(language: SandboxFile["language"]): string {
  const labels: Record<SandboxFile["language"], string> = {
    tsx: "TypeScript React",
    ts: "TypeScript",
    css: "CSS",
    json: "JSON",
  };
  return labels[language];
}

export function getLanguageBadge(language: SandboxFile["language"]): string {
  const badges: Record<SandboxFile["language"], string> = {
    tsx: "TSX",
    ts: "TS",
    css: "CSS",
    json: "JSON",
  };
  return badges[language];
}

export function formatTimestamp(date: Date): string {
  return date.toLocaleTimeString("en-US", {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

export function formatCode(content: string): string {
  const lines = content.split("\n");
  let indent = 0;
  const formatted: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      formatted.push("");
      continue;
    }

    if (/^[\}\]\)]/.test(trimmed)) {
      indent = Math.max(0, indent - 1);
    }

    formatted.push(`${"  ".repeat(indent)}${trimmed}`);

    const openBrackets = (trimmed.match(/[\{\[\(]/g) || []).length;
    const closeBrackets = (trimmed.match(/[\}\]\)]/g) || []).length;
    indent += openBrackets - closeBrackets;
    indent = Math.max(0, indent);
  }

  return formatted.join("\n");
}

export function findFileIdInTree(
  nodes: FileTreeNode[],
  fileId: string
): string | null {
  for (const node of nodes) {
    if (node.type === "file" && node.fileId === fileId) {
      return node.id;
    }
    if (node.children) {
      const found = findFileIdInTree(node.children, fileId);
      if (found) return found;
    }
  }
  return null;
}

export function removeFileFromTree(
  nodes: FileTreeNode[],
  fileId: string
): FileTreeNode[] {
  return nodes
    .filter((node) => !(node.type === "file" && node.fileId === fileId))
    .map((node) =>
      node.children
        ? { ...node, children: removeFileFromTree(node.children, fileId) }
        : node
    );
}

export function addFileToTree(
  nodes: FileTreeNode[],
  file: SandboxFile
): FileTreeNode[] {
  const parts = file.path.split("/");
  if (parts.length === 1) {
    return [
      ...nodes,
      {
        id: `tree-${file.id}`,
        name: file.name,
        type: "file" as const,
        fileId: file.id,
      },
    ];
  }

  const [folderName, ...rest] = parts;
  const folderId = `folder-${folderName}`;
  const existingFolderIndex = nodes.findIndex(
    (node) => node.type === "folder" && node.name === folderName
  );

  if (existingFolderIndex >= 0) {
    const folder = nodes[existingFolderIndex];
    const updatedFolder: FileTreeNode = {
      ...folder,
      children: addFileToTree(folder.children ?? [], {
        ...file,
        path: rest.join("/"),
      }),
    };
    return nodes.map((node, index) =>
      index === existingFolderIndex ? updatedFolder : node
    );
  }

  return [
    ...nodes,
    {
      id: folderId,
      name: folderName,
      type: "folder" as const,
      children: addFileToTree([], { ...file, path: rest.join("/") }),
    },
  ];
}

export function sandboxPanelClassName(className?: string): string {
  return [
    "overflow-hidden rounded-xl border border-white/[0.06] bg-[#101012]/90",
    className,
  ]
    .filter(Boolean)
    .join(" ");
}

export function getViewportWidth(viewport: "desktop" | "tablet" | "mobile") {
  const widths = {
    desktop: "100%",
    tablet: "768px",
    mobile: "390px",
  } as const;
  return widths[viewport];
}

export function formatRuntimeErrorForCopy(error: {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}): string {
  return `${error.title}: ${error.message}
at ${error.file}:${error.line}${error.column ? `:${error.column}` : ""}

${error.stack}`;
}
